"""Review UI: browse/compare scripts generated by scripts/eval_generation.py
(out/eval/*.json + out/generation_runs*.jsonl), and -- since the "生成" mode
below -- trigger a real generation run directly from the browser.

Every widget here reads/writes through src/bixiascribe/review.py and
src/bixiascribe/generation.py, neither of which import streamlit -- per the
武俠 RPG 劇本 RAG 架構方案 doc, Streamlit is a disposable "臨時駕駛艙" for this
stage, meant to be swappable for a Tauri desktop app later without touching
the data/generation layers. The 生成 mode runs a real crew (API key + Chroma
index required); the other three modes stay read-only, no tokens spent.

Run with:
    pip install -r requirements-ui.txt
    .venv/bin/streamlit run ui/app.py
"""
from __future__ import annotations

import logging
import sys
from pathlib import Path

_REPO_ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(_REPO_ROOT / "src"))

import streamlit as st  # noqa: E402

# streamlit 的 hot-reload watcher 會走訪所有已載入模組取路徑，碰到 transformers
# 的 lazy __getattr__ 會把每個 image-processor 模組 import 一次；本專案沒裝
# torchvision，於是啟動時被上百段 ModuleNotFoundError traceback 洗版
# (local_sources_watcher.py's _LOGGER.warning(..., exc_info=True))。只降這一個
# logger 的等級，hot reload 與其他 streamlit 警告都保留。
logging.getLogger("streamlit.watcher.local_sources_watcher").setLevel(logging.ERROR)

from bixiascribe import (  # noqa: E402
    catalog,
    config,
    estimate,
    generation,
    length,
    library,
    pricing,
)
from bixiascribe.review import (  # noqa: E402
    RunRecord,
    ScriptRecord,
    chapter_names,
    clue_names,
    discover_resumable_runs,
    discover_scripts,
    event_titles,
    faction_names,
    group_by_requirement,
    load_run_records,
    load_script,
    npc_names,
    overview_rows,
    requirement_slug,
    role_keys_for_mode,
    run_role_models,
    variant_names,
)
from bixiascribe.schema import Event, Script, validate_references  # noqa: E402

_CATALOG = catalog.load_catalog()

st.set_page_config(page_title="BiXiaScribe 劇本檢視", layout="wide")

# Catches the exact failure mode that motivated this check: `streamlit run
# ui/app.py` resolved via a system/anaconda `streamlit` on PATH instead of
# `.venv/bin/streamlit` -- the app still imports and runs fine (streamlit
# itself doesn't care), but the interpreter's torch is then too old for
# bge-m3 (see embedding.py::check_backend_env()), and every
# wuxia_corpus_search call during a real generation silently degrades to a
# "檢索失敗" text message for the whole run (crew/tools.py never raises on
# this). Read-only browsing still works under the wrong interpreter, so this
# warns rather than st.stop()s.
_venv_dir = _REPO_ROOT / ".venv"
if _venv_dir.is_dir() and Path(sys.prefix).resolve() != _venv_dir.resolve():
    st.error(
        f"⚠ 目前 Streamlit 跑在 `{sys.executable}`，不是專案的 `.venv`。"
        "語料檢索（wuxia_corpus_search）很可能會靜默失敗。請改用：\n\n"
        "```\n.venv/bin/streamlit run ui/app.py\n```"
    )


# ---- cached data access ----


@st.cache_data(show_spinner=False)
def _index(include_checkpoints: bool = True) -> list[ScriptRecord]:
    return discover_scripts(include_checkpoints=include_checkpoints)


@st.cache_data(show_spinner=False)
def _overview(include_checkpoints: bool = True) -> list[dict]:
    return overview_rows(_index(include_checkpoints))


@st.cache_data(show_spinner=False)
def _script(path_str: str, mtime: float) -> Script:
    # mtime is part of the cache key so an edited/regenerated file on disk
    # invalidates the cached parse automatically.
    return load_script(Path(path_str))


def _load(rec: ScriptRecord) -> Script | None:
    if rec.path is None:
        return None
    try:
        return _script(str(rec.path), rec.path.stat().st_mtime)
    except Exception:
        # A malformed/unreadable script file (or, in principle, a
        # checkpoint whose envelope this process's Script schema can't
        # validate) shouldn't crash the whole page with a raw traceback --
        # callers show an st.error instead. overview_rows() already has its
        # own equivalent guard for the same reason.
        return None


def _record_label(rec: ScriptRecord, *, disambiguate: bool = False) -> str:
    rep_suffix = f" (rep{rec.rep})" if rec.rep else ""
    label = f"{rec.variant}{rep_suffix}"
    if disambiguate:
        # Same (variant, rep) can be shared by more than one ScriptRecord --
        # e.g. a legacy out/eval/ file and a layered run-only failure both
        # logged under variant="baseline", rep=0. mode/source disambiguates
        # which one this is without changing the variant dropdown itself.
        mode = rec.run.mode if rec.run else ""
        label += f" [{mode or rec.source}]"
    return label


def _requirement_label(key: str, records: list[ScriptRecord]) -> str:
    slug = records[0].slug if records else ""
    short = key if len(key) <= 30 else key[:30] + "…"
    return f"{short}  ({slug})" if slug else short


# ---- shared render helpers ----


def _format_cost_metric(run) -> str:
    """`run.cost_usd` is `None` whenever pricing.estimate_cost() couldn't
    price the run (no token_usage at all -- e.g. a checkpoint-only
    "checkpoint:<run_id>" record, which never carries usage -- or a model
    id missing from eval/model_prices.json), never a real $0. st.metric
    can't show a caption under the number, so callers pair this with
    _cost_caption() below rather than trying to cram both into one
    string."""
    return f"${run.cost_usd:.4f}" if run.cost_usd is not None else "—"


def _cost_caption(run) -> str:
    if run.cost_usd is None:
        return (
            "成本：無法定價（不代表免費——多半是沒有 token_usage 可算，"
            "或模型不在 eval/model_prices.json）"
        )
    basis = run.cost_basis or "unknown_price"
    note = "｜⚠ 缺快取價格，此為高估值" if basis.endswith("_uncached_price_missing") else ""
    return f"定價依據：{basis}{note}"


def _render_estimate(result, *, label: str = "預估") -> None:
    """One `bixiascribe.estimate.RunEstimate` rendered as a 3-metric row +
    range captions + a plain-Chinese basis explanation -- shared by the
    pre-run form, the live progress fragment, and the batch-confirmation
    panel (see estimate.py's module docstring for the basis priority).
    Cost/time follow the same "None -> — , never a bare $0/0" convention
    _format_cost_metric() already uses -- a missing price or a not-yet-known
    beat count must never read as free/instant.

    result.seconds_low/seconds_high/cost_low/cost_high were always computed
    (0.7x/1.5x for a pre-run guess, tighter for a mid-run estimate) but
    never rendered before this -- the UI showed one point number that read
    as far more precise/authoritative than a "prior"-basis guess actually
    is."""
    cols = st.columns(3)
    cols[0].metric(f"{label}場次", result.scenes if result.scenes is not None else "—")
    cols[1].metric(
        f"{label}耗時",
        f"{result.seconds / 60:.1f} 分" if result.seconds is not None else "—",
    )
    if result.seconds_low is not None and result.seconds_high is not None:
        cols[1].caption(f"{result.seconds_low / 60:.1f}–{result.seconds_high / 60:.1f} 分")
    cols[2].metric(
        f"{label}成本",
        f"${result.cost_usd:.4f}" if result.cost_usd is not None else "—",
    )
    if result.cost_low is not None and result.cost_high is not None:
        cols[2].caption(f"${result.cost_low:.4f}–${result.cost_high:.4f}")

    explain = estimate.BASIS_EXPLANATION.get(result.basis, result.basis)
    st.caption(f"依據：{result.basis}——{explain}")
    if result.basis == "prior":
        st.caption("⚠ 這個數字的不確定性很大，請把上面的區間當成真正的範圍。")
    if result.cost_usd is None:
        st.caption("無法定價（不代表免費）")
    # estimate_run()/estimate_remaining() already append a parallelism≈1.0
    # note to result.notes when relevant -- printed below alongside every
    # other note rather than duplicated with a second caption here.
    for note in result.notes:
        st.caption(f"　{note}")


def _render_role_models(run) -> None:
    """One column per agent role run.mode actually used (review.
    run_role_models()), each with a popover showing the full model id, the
    role's note, price, tool-support, and tested status from the catalog --
    replaces the two previously-hardcoded 3-column blocks (legacy's own 3
    roles, layered's stale 3-of-4, missing "proof") with one loop that can't
    diverge from generation._cost_models()'s role set (see design.md 實測四)."""
    role_models = run_role_models(run)
    cols = st.columns(len(role_models)) if role_models else []
    for col, (role, model_id) in zip(cols, role_models):
        role_info = _CATALOG.roles.get(role)
        role_label = role_info.label if role_info else role
        with col:
            st.write(f"**{role_label}**：{model_id or '—'}")
            with st.popover("詳情", disabled=not model_id):
                if not model_id:
                    st.caption("（未設定）")
                else:
                    model_info = _CATALOG.describe(model_id)
                    st.code(model_id, language=None)
                    if role_info and role_info.note:
                        st.caption(role_info.note)
                    st.caption(f"狀態：{model_info.status}")
                    if model_info.description:
                        st.caption(model_info.description)
                    if model_info.price is not None:
                        p = model_info.price
                        tool_note = "支援" if p.supports_tools else "不支援"
                        st.caption(
                            f"價格：${p.prompt_usd_per_1m:.4f} / "
                            f"${p.completion_usd_per_1m:.4f} per 1M tokens"
                            f"（{tool_note} tool calling）"
                        )
                    else:
                        st.caption("價格：未知（不在 eval/model_prices.json）")


def _render_run_meta(run) -> None:
    if run is None:
        st.caption("沒有對應的執行紀錄（metadata 來源：檔名推斷）")
        return
    _render_role_models(run)
    if run.mode == "layered":
        cols = st.columns(5)
        cols[0].metric("耗時 (s)", f"{run.elapsed_s:.1f}")
        cols[1].metric("scenes_generated", run.scenes_generated)
        cols[2].metric("retrieval_calls", run.retrieval_calls)
        cols[3].metric("total_tokens", run.token_usage.get("total_tokens", "—"))
        cols[4].metric("成本 (USD)", _format_cost_metric(run))
    else:
        cols = st.columns(5)
        cols[0].metric("耗時 (s)", f"{run.elapsed_s:.1f}")
        cols[1].metric("retrieval_calls", run.retrieval_calls)
        cols[2].metric("repair_attempts", run.repair_attempts)
        cols[3].metric("total_tokens", run.token_usage.get("total_tokens", "—"))
        cols[4].metric("成本 (USD)", _format_cost_metric(run))
    completion_tokens = run.token_usage.get("completion_tokens") or 0
    reasoning_tokens = run.token_usage.get("reasoning_tokens") or 0
    if completion_tokens:
        st.caption(
            f"reasoning tokens 占 completion 比例：{reasoning_tokens / completion_tokens:.1%}"
            f"（{reasoning_tokens} / {completion_tokens}；已計入 completion_tokens 的計價中，"
            "非另計費用——見 pricing.py 決策六）"
        )
    if run.reasoning_effort:
        st.caption(f"reasoning_effort：{run.reasoning_effort}")
    st.caption(
        f"coerced_from：{run.coerced_from or '—'} ｜ 來源紀錄：{run.source_log or '—'} ｜ "
        f"{_cost_caption(run)}"
    )
    if not run.retrieval_enabled:
        st.info("本次刻意未使用語料檢索（不檢索語料庫）。")
    elif run.retrieval_calls == 0:
        st.warning("⚠ 對話 agent 從未呼叫 wuxia_corpus_search（retrieval_calls = 0）")
    if run.retrieval_failures > 0:
        st.error(
            f"⚠ 語料檢索失敗 {run.retrieval_failures} 次"
            "——請確認是用 `.venv/bin/streamlit` 執行、且索引已建立。"
        )
    if run.retrieval_queries:
        st.code("\n".join(run.retrieval_queries), language=None)
    if run.structured_fallbacks:
        with st.expander(f"⚠ 模型輸出降級紀錄（{run.structured_fallbacks} 次改用自由文字模式）"):
            st.code("\n".join(run.llm_notes), language=None)
    if run.normalize_notes:
        with st.expander(f"機械式修正紀錄（{len(run.normalize_notes)} 項）"):
            st.code("\n".join(run.normalize_notes), language=None)
    if run.quality_problems:
        with st.expander(f"⚠ 品質檢查清單未通過（{len(run.quality_problems)} 項，僅供參考不擋關）"):
            st.code("\n".join(run.quality_problems), language=None)
    if run.scene_metrics:
        with st.expander(f"每場執行歸因（{len(run.scene_metrics)} 場，依耗時排序）"):
            rows = sorted(run.scene_metrics, key=lambda r: r.get("elapsed_s") or 0, reverse=True)
            st.dataframe(
                [
                    {
                        "beat_id": r.get("beat_id", ""),
                        "總秒數": round(r.get("elapsed_s") or 0, 1),
                        "最後一次呼叫秒數": round(r.get("call_elapsed_s") or 0, 1),
                        "修補秒數": round(r.get("repair_elapsed_s") or 0, 1),
                        "LLM 呼叫": r.get("llm_calls", 0),
                        "reasoning tokens": r.get("reasoning_tokens", 0),
                        "guardrail 重試": r.get("guardrail_retries", 0),
                        "檢索次數": r.get("retrieval_calls", 0),
                    }
                    for r in rows
                ],
                use_container_width=True,
            )
    if run.error:
        st.error(run.error)


def _render_event(
    event: Event,
    names: dict[str, str],
    titles: dict[str, str],
    chapters: dict[str, str] | None = None,
    clues: dict[str, str] | None = None,
) -> None:
    chapters = chapters or {}
    clues = clues or {}
    st.caption(event.summary)
    tags = []
    if event.chapter_id:
        tags.append(f"章節：{chapters.get(event.chapter_id, f'⚠️ {event.chapter_id}')}")
    if tags:
        st.caption(" ｜ ".join(tags))
    if event.clue_ids:
        clue_labels = [clues.get(c, f"⚠️ {c}") for c in event.clue_ids]
        st.caption(f"線索：{'、'.join(clue_labels)}")
    for cond in event.preconditions:
        st.caption(f"前提：{cond}")

    if not event.dialogue:
        st.caption("（無對話）")
    for line in event.dialogue:
        speaker = names.get(line.npc, f"⚠️ {line.npc}")
        st.markdown(f"**{speaker}**：{line.line}")

    if event.check is not None:
        check = event.check
        fallback = (
            f"失敗 → {titles.get(check.on_fail, check.on_fail)}"
            if check.on_fail
            else "⚠️ 無失敗路線"
        )
        success_label = titles.get(check.on_pass, check.on_pass or "—")
        st.caption(
            f"🎲 檢定｜成功 → {success_label}｜{fallback}"
            + (f"｜失敗代價：{check.fail_cost}" if check.fail_cost else "")
        )

    for choice in event.choices:
        target = titles.get(choice.next, f"⚠️ {choice.next}")
        st.markdown(f"↳ **{choice.text}** → {target}")
        if choice.effects:
            st.caption(f"效果：{choice.effects}（{choice.delta:+d}）")
        choice_tags = []
        if choice.cost:
            choice_tags.append(f"代價：{choice.cost}")
        if choice.payoff_at:
            payoff_label = chapters.get(choice.payoff_at, choice.payoff_at)
            choice_tags.append(f"延遲回收：{payoff_label}")
        if choice_tags:
            st.caption("　" + " ｜ ".join(choice_tags))


def _render_script(script: Script, rec: ScriptRecord) -> None:
    st.subheader(script.meta.title)
    st.caption(script.meta.theme)

    problems = validate_references(script)
    if problems:
        st.error("交叉參照有問題：\n" + "\n".join(f"- {p}" for p in problems))
    else:
        st.success("交叉參照無誤")

    metrics = overview_rows([rec])[0]
    cols = st.columns(5)
    cols[0].metric("事件", metrics["events"])
    cols[1].metric("NPC", metrics["npcs"])
    cols[2].metric("分支", metrics["branches"])
    cols[3].metric("對話句數", metrics["dialogue_lines"])
    cols[4].metric("平均句長", f"{metrics['avg_line_chars']:.1f}")

    st.download_button(
        "匯出 JSON",
        data=library.export_bytes(script),
        file_name=library.export_filename(rec),
        mime="application/json",
        key=f"export_{rec.key}",
    )

    names = npc_names(script)
    titles = event_titles(script)
    chapters = chapter_names(script)
    clues = clue_names(script)
    factions = faction_names(script)

    (
        tab_events, tab_npc, tab_rpg, tab_chapters, tab_factions,
        tab_clues, tab_truth, tab_endings, tab_run, tab_json,
    ) = st.tabs(
        [
            "事件", "NPC", "玩家/道具", "章節", "勢力", "線索",
            "真相", "結局", "執行紀錄", "原始 JSON",
        ]
    )
    with tab_events:
        for i, event in enumerate(script.events):
            with st.expander(f"{i + 1}. {event.title}", expanded=(i == 0)):
                _render_event(event, names, titles, chapters, clues)
    with tab_npc:
        npc_rows = [
            {
                **n.model_dump(),
                "所屬勢力": factions.get(n.faction_id, "—") if n.faction_id else "—",
            }
            for n in script.npcs
        ]
        st.dataframe(npc_rows, width="stretch")
    with tab_rpg:
        if script.player:
            st.markdown(f"**玩家**：{script.player.name}（出身：{script.player.origin}；弱點：{script.player.flaw}）")
            if script.player.token:
                st.caption(f"信物：{script.player.token}")
        else:
            st.caption("（此劇本沒有 player 欄位）")
        if script.stat:
            st.caption(f"唯一數值：{script.stat.name}（初始值 {script.stat.init}）")
        st.markdown("**道具**")
        if script.items:
            item_rows = [
                {
                    **i.model_dump(),
                    "取得場次": (
                        titles.get(i.from_event, "（一開始就持有）")
                        if i.from_event
                        else "（一開始就持有）"
                    ),
                }
                for i in script.items
            ]
            st.dataframe(item_rows, width="stretch")
        else:
            st.caption("（無）")
    with tab_chapters:
        if script.chapters:
            for chapter in script.chapters:
                with st.expander(f"{chapter.title}", expanded=False):
                    st.caption(chapter.summary)
                    if chapter.loc:
                        st.caption(f"地點：{chapter.loc}")
                    if chapter.start_event:
                        start_label = titles.get(chapter.start_event, chapter.start_event)
                        st.caption(f"起始場次：{start_label}")
        else:
            st.caption("（無）")
    with tab_factions:
        if script.factions:
            for faction in script.factions:
                st.markdown(f"**{faction.name}**：{faction.motive}")
        else:
            st.caption("（無）")
    with tab_clues:
        if script.clues:
            clue_rows = [
                {**c.model_dump(), "found_in": titles.get(c.from_event, "—")}
                for c in script.clues
            ]
            st.dataframe(clue_rows, width="stretch")
        else:
            st.caption("（無）")
    with tab_truth:
        if script.truth:
            st.markdown("**公開**")
            st.write(script.truth.public or "（無）")
            st.markdown("**逐步揭露**")
            if script.truth.revealed:
                for fact in script.truth.revealed:
                    st.caption(f"・{fact}")
            else:
                st.caption("（無）")
            st.markdown("**私藏（不應提前出現於場景內容）**")
            st.write(script.truth.hidden or "（無）")
        else:
            st.caption("（此劇本沒有 truth 欄位）")
    with tab_endings:
        if script.endings:
            for ending in script.endings:
                st.markdown(f"**{ending.name}**")
                st.caption(ending.description)
                st.caption(f"　區間：[{ending.min}, {ending.max}]")
        else:
            st.caption("（無）")
    with tab_run:
        _render_run_meta(rec.run)
        if rec.source != "jsonl":
            st.info(f"metadata 來源：{rec.source}（找不到對應的 JSONL 執行紀錄）")
    with tab_json:
        st.json(script.model_dump())


@st.dialog("確認刪除")
def _confirm_delete_dialog(rec: ScriptRecord) -> None:
    st.write(f"確定要刪除「{rec.variant}」（{rec.slug or rec.key}, rep{rec.rep}）嗎？")
    if rec.source == "checkpoint":
        st.warning("將刪除整個 .bixia_state/<run_id>/ 目錄，無法復原。")
    else:
        st.caption(
            "只刪除劇本檔案本身，out/generation_runs*.jsonl 的執行紀錄仍會保留"
            "（重新整理後以「run-only」重新出現）。"
        )
    col1, col2 = st.columns(2)
    if col1.button("確定刪除", type="primary", key=f"confirm_delete_{rec.key}"):
        try:
            library.delete_record(rec)
        except ValueError as exc:
            st.error(str(exc))
        else:
            # Clear cached discovery *before* st.rerun() -- otherwise the
            # rerun could still serve the stale cached record list.
            st.cache_data.clear()
            st.rerun()
    if col2.button("取消", key=f"cancel_delete_{rec.key}"):
        st.rerun()


def _render_delete_button(rec: ScriptRecord) -> None:
    """A delete button feeding _confirm_delete_dialog() -- omitted for
    source="adhoc" records, which were never copied into scripts_dir/
    state_dir and so have nothing library.delete_record() is allowed to
    touch (see design.md's path-escape mitigation)."""
    if rec.source == "adhoc":
        return
    if st.button("刪除此紀錄", key=f"delete_{rec.key}"):
        _confirm_delete_dialog(rec)


# ---- generation mode helpers ----


def _record_for_result(res: generation.GenerationResult) -> ScriptRecord:
    """Wrap a fresh GenerationResult in the same ScriptRecord shape
    discover_scripts() produces from disk, so _render_script/_render_run_meta
    render a just-generated script with zero new render code."""
    return ScriptRecord(
        key=res.script_path.stem if res.script_path else f"{res.variant}@pending",
        path=res.script_path,
        variant=res.variant,
        slug=requirement_slug(res.requirement),
        rep=res.rep,
        requirement=res.requirement,
        run=RunRecord.from_row(res.row, source_log=generation.UI_RUN_LOG.name),
        source="jsonl" if res.script_path else "run-only",
    )


@st.fragment(run_every=1.0)
def _render_generation_progress(job: generation.GenerationJob) -> None:
    snap = job.snapshot()

    if snap.status == "running":
        # A batch awaiting confirmation is rendered by the static
        # _render_batch_confirmation() below instead, outside this
        # every-1s-repainting fragment -- inside the fragment, a button
        # click could get wiped out by the next repaint landing mid-click.
        # Leaving this fragment via st.rerun() hands control to the page's
        # non-fragment branch (see the "生成" mode body), which re-checks
        # snap.awaiting_confirmation on every full rerun.
        if snap.awaiting_confirmation:
            st.rerun()

        # scenes_total > 0 means the beat sheet is ready -- a real
        # denominator, so a determinate progress bar instead of the old
        # phase_index/phase_total fraction (which for layered mode was
        # always 0/0 -- see JobSnapshot's docstring on phase_total).
        est = job.estimate()  # internally cached (default 5s), see its docstring
        stage_label = snap.stage or snap.phase or "準備中"
        if snap.scenes_total:
            st.progress(min(1.0, snap.scenes_done / snap.scenes_total))
            st.caption(f"{stage_label} · 第 {snap.scenes_done}/{snap.scenes_total} 場")
        else:
            st.progress(0.0)
            st.caption(f"{stage_label} · 尚在拆書/排場，場次數未定")

        if snap.active_scene_ids:
            st.caption(
                f"進行中：{'、'.join(snap.active_scene_ids)}"
                f"（本場已 {snap.active_scene_elapsed_s:.0f}s）"
            )

        # est.basis == "measured_run" means est.seconds is already the
        # *remaining* time (estimate.estimate_remaining()'s contract) --
        # anything else (a pre-run "prior"/"history_*" fallback) means
        # est.seconds is a *total*, so remaining = total - elapsed. Getting
        # this branch wrong doubles the ETA, so it stays explicit rather
        # than folded into one expression.
        if est.basis == "measured_run":
            remaining = est.seconds
        elif est.seconds is not None:
            remaining = max(0.0, est.seconds - snap.elapsed_s)
        else:
            remaining = None
        eta_line = f"已耗時 {snap.elapsed_s:.0f}s"
        if remaining is not None:
            eta_line += f" · 剩餘約 {remaining / 60:.1f} 分"
            eta_line += f" · 預計總計 {(snap.elapsed_s + remaining) / 60:.1f} 分"
        else:
            eta_line += " · 剩餘時間未知"
        st.caption(eta_line)

        if snap.guardrail_retries:
            st.warning(
                f"⚠ guardrail 已重試 {snap.guardrail_retries} 次"
                f"（每場上限 {config.GUARDRAIL_MAX_RETRIES} 次，超過即整趟失敗）"
            )

        if snap.log:
            st.code("\n".join(snap.log[-12:]), language=None)

        _render_estimate(est, label="總計")

        if st.button("取消", key="cancel_gen"):
            job.cancel()
        return

    # Terminal state: clear cached discovery so the new script/row shows up
    # elsewhere, then leave the fragment for a full-app rerun.
    st.cache_data.clear()
    if snap.status == "done" and snap.result is not None and snap.result.ok:
        st.session_state["gen_last_result"] = snap.result
    elif snap.status == "cancelled":
        # snap.result carries whatever row generate() managed to write for
        # the tokens already spent before the cancellation (see
        # generation.GenerationJob._run()'s GenerationCancelled handler) --
        # stashed in its own session_state key (not gen_last_result/
        # gen_last_error, which the "done"/"failed" branches below already
        # own) so the post-rerun body can still show the cost instead of
        # the st.warning() here vanishing on this immediate st.rerun().
        st.session_state["gen_cancelled_result"] = snap.result
    else:
        st.session_state["gen_last_result"] = snap.result  # may be None
        st.session_state["gen_last_error"] = snap.error or (
            snap.result.error if snap.result else "生成失敗（原因不明）。"
        )
    del st.session_state["gen_job"]
    st.rerun()


def _render_batch_confirmation(job: generation.GenerationJob, snap: generation.JobSnapshot) -> None:
    """Static (non-fragment) panel shown while a layered run's scenes batch
    is staged awaiting confirm_batch()/reject_batch() -- rendered outside
    _render_generation_progress()'s @st.fragment(run_every=1.0) so a button
    click can't be wiped out by the next automatic repaint landing mid-click
    (see that function's docstring). Renders the staged scenes' actual
    content (via the existing _render_event, zero new render code) instead
    of just their beat ids, so confirming isn't a blind decision."""
    st.subheader("本批場次待確認")
    st.caption(f"run_id：{snap.run_id} ｜ 已耗時 {snap.elapsed_s:.0f}s")
    _render_estimate(job.estimate(), label="確認後預計總計")

    scenes = job.pending_scenes()
    names, titles = job.scene_context()
    if not scenes:
        st.info(f"本批已生成 {len(snap.pending_scene_ids)} 場：{'、'.join(snap.pending_scene_ids)}")
    for i, event in enumerate(scenes):
        with st.expander(f"{i + 1}. {event.title}", expanded=(i == 0)):
            _render_event(event, names, titles)

    col1, col2, col3 = st.columns(3)
    if col1.button("確認繼續", key="confirm_batch"):
        job.confirm_batch()
        st.rerun()
    if col2.button("重新生成本批", key="reject_batch"):
        job.reject_batch()
        st.rerun()
    if col3.button("取消", key="cancel_gen_confirm"):
        job.cancel()
        st.rerun()


