with st.sidebar.expander("匯入劇本"):
    _uploaded = st.file_uploader("上傳劇本 JSON", type="json")
    _import_variant = st.text_input("variant")
    _import_requirement = st.text_area("requirement", height=80)
    # Explicit import button (not import-on-upload) -- st.file_uploader
    # re-delivers its buffered content on every rerun, so an
    # import-on-upload path would re-import the same file on any unrelated
    # widget interaction.
    if st.button("匯入"):
        if _uploaded is None:
            st.error("請先選擇檔案。")
        elif not _import_variant.strip() or not _import_requirement.strip():
            st.error("variant 與 requirement 都必須填寫。")
        else:
            try:
                out_path = library.import_script(
                    _uploaded.getvalue(),
                    variant=_import_variant.strip(),
                    requirement=_import_requirement.strip(),
                )
            except library.ImportRejected as exc:
                st.error(str(exc))
            else:
                st.cache_data.clear()
                st.success(f"已匯入：`{out_path}`")
                st.rerun()

with st.sidebar.expander("Ad hoc 載入（僅檢視，不複製進 out/eval/）"):
    _adhoc_path = st.text_input("檔案路徑")
    if st.button("載入"):
        try:
            _script, _rec = library.load_ad_hoc(Path(_adhoc_path.strip()))
        except Exception as exc:  # noqa: BLE001 -- surfaced to the user, not fatal
            st.error(f"載入失敗：{exc}")
        else:
            st.session_state["adhoc_record"] = (_script, _rec)
            st.rerun()

mode_options = ["單篇閱讀", "並排比較", "總覽表", "生成"]
if "adhoc_record" in st.session_state:
    mode_options = ["Ad hoc 檢視", *mode_options]
default_mode = "生成" if not records else mode_options[0]
mode = st.sidebar.radio("模式", mode_options, index=mode_options.index(default_mode))

groups = group_by_requirement(records)
requirement_keys = list(groups.keys())

if mode not in ("生成", "Ad hoc 檢視") and not records:
    st.warning(
        "找不到任何已生成的劇本。用左側的「生成」模式產生一份，或先跑：\n\n"
        "```\npython scripts/eval_generation.py --dry-run   # 先零成本檢查\n"
        "python scripts/eval_generation.py                # 實際生成\n```"
    )
    st.stop()

if mode == "Ad hoc 檢視":
    st.title("Ad hoc 檢視")
    script, rec = st.session_state["adhoc_record"]
    st.caption(f"路徑：`{rec.path}`（未複製進 out/eval/，僅供本次檢視）")
    _render_script(script, rec)
    if st.button("清除"):
        del st.session_state["adhoc_record"]
        st.rerun()

elif mode == "生成":
    st.title("生成新劇本")

    job: generation.GenerationJob | None = st.session_state.get("gen_job")
    if job is not None:
        job_snap = job.snapshot()
        if job_snap.status == "running" and job_snap.awaiting_confirmation:
            # Rendered outside the every-1s @st.fragment so a button click
            # can't be wiped out by an automatic repaint mid-click -- see
            # _render_batch_confirmation()'s docstring.
            _render_batch_confirmation(job, job_snap)
        else:
            _render_generation_progress(job)
        st.stop()

    # The UI is fixed to "layered" -- legacy runs take 269-1572s per
    # out/generation_runs*.jsonl's real legacy rows, which makes it
    # unusable interactively. config.PIPELINE_MODE ("legacy" default,
    # config.py:174) remains the CLI/scripts rollback lever
    # (scripts/generate_script.py, scripts/eval_generation.py); it is no
    # longer read here. review.role_keys_for_mode's legacy branch, the
    # review tab's legacy rendering (_render_run_meta), and the 17
    # historical legacy rows already in out/generation_runs*.jsonl are all
    # unaffected -- this only removes the toggle from the *generation* form.
    gen_mode = "layered"

    resume_run = None
    resumable_runs = discover_resumable_runs()
    if resumable_runs:
        with st.expander("續跑未完成的執行"):
            resume_choice = st.selectbox(
                "選擇要續跑的執行",
                [None, *resumable_runs],
                format_func=lambda r: (
                    "（不續跑，開始新的一次）"
                    if r is None
                    else f"{r.run_id}（{r.stage}，已完成 {len(r.completed_scene_ids)} 場，"
                    f"schema v{r.schema_version}）"
                ),
            )
            if resume_choice is not None:
                if resume_choice.schema_version != generation.CHECKPOINT_SCHEMA_VERSION:
                    found = resume_choice.schema_version
                    current = generation.CHECKPOINT_SCHEMA_VERSION
                    st.error(
                        f"此檢查點的 schema_version={found} 與目前管線的 {current} 不符——"
                        "續跑不會沿用任何已完成階段，會從拆書重新生成，花費等同全新一次"
                        "執行。已取消此次續跑選擇。"
                    )
                else:
                    st.warning(
                        "此檢查點沒有記錄原本的變體/篇幅/檢索/推理強度設定——續跑會套用你現在"
                        "選的設定，可能與已完成階段不一致。"
                    )
                    resume_run = resume_choice

    if resume_run is not None:
        requirement = st.text_area(
            "劇情需求（續跑：鎖定為原檢查點內容）",
            value=resume_run.requirement,
            height=140,
            disabled=True,
        )
    else:
        requirement = st.text_area("劇情需求", height=140, key="gen_requirement")

    all_variants = [v for v in generation.load_variants() if v.ui_visible]
    variant_choice = st.selectbox(
        "模型變體",
        [*all_variants, "自訂"],
        format_func=lambda v: v if isinstance(v, str) else v.name,
    )
    if variant_choice == "自訂":
        with st.expander("自訂模型", expanded=True):
            custom_models: dict[str, str] = {}
            for role in role_keys_for_mode(gen_mode):
                role_info = _CATALOG.roles.get(role)
                options = _CATALOG.selectable(role)
                if not options:
                    st.warning(f"catalog 沒有適用於「{role}」角色的可選模型。")
                    custom_models[role] = ""
                    continue
                selected = st.selectbox(
                    role_info.label if role_info else role,
                    options,
                    format_func=catalog.model_label,
                    key=f"custom_model_{role}",
                )
                custom_models[role] = selected.model_id
        variant = generation.Variant(name="custom", **custom_models)
    else:
        variant = variant_choice
        if variant.note:
            st.caption(variant.note)

    reasoning_options = list(_CATALOG.reasoning_efforts) or ["default"]
    default_reasoning = (
        config.REASONING_EFFORT
        if config.REASONING_EFFORT in reasoning_options
        else reasoning_options[0]
    )
    reasoning_effort = st.selectbox(
        "推理強度（reasoning_effort）",
        reasoning_options,
        index=reasoning_options.index(default_reasoning),
        format_func=lambda v: (
            _CATALOG.reasoning_efforts[v].label if v in _CATALOG.reasoning_efforts else v
        ),
    )
    _reasoning_info = _CATALOG.reasoning_efforts.get(reasoning_effort)
    if _reasoning_info and _reasoning_info.note:
        st.caption(_reasoning_info.note)

    no_retrieval = st.checkbox(
        "不檢索語料庫（省 token，改用模型自身武俠語感）",
        value=not (
            variant.use_retrieval if variant.use_retrieval is not None else config.RETRIEVAL_ENABLED
        ),
        help="關閉後，對話/scene_writer agent 不會呼叫 wuxia_corpus_search——"
        "不需要 Chroma 索引或本機 embedding 模型，也能省下最大宗的 token 花費"
        "（見 CLAUDE.md 的模型組合 A/B 數據：retrieval 呼叫次數與 token 用量高度相關）。"
        "適合測試 glm-5.2 等武俠語感本身較好的模型是否真的需要語料檢索。",
    )

    # Default to the selected variant's own script_length so picking a
    # predefined variant (not 自訂) preserves its declared length unless the
    # user actively changes the selector -- see design.md's "UI length
    # selector UX".
    variant_script_length = variant.script_length or "short"
    length_presets = ("short", "medium", "long")
    if variant_script_length in length_presets:
        default_length_option = variant_script_length
        default_custom_targets = length.parse_length_spec("short").targets
    else:
        default_length_option = "自訂"
        default_custom_targets = length.parse_length_spec(variant_script_length).targets

    length_option = st.selectbox(
        "劇本篇幅",
        [*length_presets, "自訂"],
        index=[*length_presets, "自訂"].index(default_length_option),
    )
    if length_option == "自訂":
        with st.expander("自訂篇幅", expanded=True):
            st.caption("以下四個欄位都只是提示模型的目標，沒有任何機制強制它一定達成。")
            custom_length_values: dict[str, str] = {}
            for field_name, field_info in length.FIELD_HELP.items():
                affects = field_info["affects"]
                if field_name == "events":
                    # events only ever reaches the legacy prompt
                    # (crew/tasks.py) -- the UI is layered-only now, so this
                    # field never changes the generated script. It still
                    # controls the pre-run scene-count/cost/time estimate
                    # (estimate._scene_count_from_target's legacy branch,
                    # via events_scale), so it stays visible rather than
                    # hidden -- hiding it would make the custom-length
                    # estimate uncontrollable.
                    suffix = "　⚠ 僅影響預估場次/成本/時間，不影響本模式產出內容"
                elif affects != "both" and affects != gen_mode:
                    suffix = f"　{length._AFFECTS_LABEL[affects]}"
                else:
                    suffix = ""
                custom_length_values[field_name] = st.text_input(
                    field_info["label"] + suffix,
                    value=default_custom_targets[field_name],
                    help=field_info["help"],
                )
            st.dataframe(
                [{"preset": name, **fields} for name, fields in length.PRESETS.items()],
                width="stretch",
            )
        script_length = (
            "custom:"
            + ",".join(f"{k}={v}" for k, v in custom_length_values.items())
        )
    else:
        script_length = length_option

    # Hoisted once, passed into every estimate_for_form() call below --
    # estimate_run() itself calls pricing.load_prices() (re-parses
    # eval/model_prices.json, no cache) and estimate.load_history() (globs +
    # parses every out/generation_runs*.jsonl row) when not given these, so
    # without hoisting, the 4 calls this section makes (3 presets + the
    # selected length) would mean 4x the disk/parse work on every widget
    # interaction that reruns this page.
    _prices = pricing.load_prices()
    _history = estimate.load_history()

    _preset_rows = []
    for _preset in ("short", "medium", "long"):
        _e = generation.estimate_for_form(
            variant, pipeline_mode="layered", script_length=_preset,
            use_retrieval=not no_retrieval, prices=_prices, history=_history,
        )
        _preset_rows.append({
            "篇幅": _preset,
            "預估場次": _e.scenes if _e.scenes is not None else "—",
            "預估耗時": f"{_e.seconds / 60:.0f} 分" if _e.seconds is not None else "—",
            "耗時區間": (
                f"{_e.seconds_low / 60:.0f}–{_e.seconds_high / 60:.0f} 分"
                if _e.seconds_low is not None else "—"
            ),
            "預估成本": f"${_e.cost_usd:.4f}" if _e.cost_usd is not None else "—",
        })
    with st.expander("各篇幅預估比較（按「開始生成」前先看這個）", expanded=True):
        st.dataframe(_preset_rows, width="stretch", hide_index=True)

    _render_estimate(
        generation.estimate_for_form(
            variant,
            pipeline_mode="layered",
            script_length=script_length,
            use_retrieval=not no_retrieval,
            prices=_prices,
            history=_history,
        )
    )

    problems = generation.preflight(check_index=not no_retrieval, check_embedding=not no_retrieval)
    ignore_checks = False
    if problems:
        for p in problems:
            st.error(p)
        ignore_checks = st.checkbox("忽略檢查，仍要執行（例如 LLM_BACKEND=fake 的離線測試）")

    disabled = bool(requirement.strip()) is False or (bool(problems) and not ignore_checks)
    if st.button("開始生成", disabled=disabled):
        ui_variant = generation.Variant(
            name=generation.ui_variant_name(variant.name),
            note=variant.note,
            writer=variant.writer,
            dialogue=variant.dialogue,
            proof=variant.proof,
            extractor=variant.extractor,
            beat_expander=variant.beat_expander,
            scene_writer=variant.scene_writer,
            session_doc_max_tokens=variant.session_doc_max_tokens,
            script_length=variant.script_length,
            use_retrieval=not no_retrieval,
            reasoning_effort=reasoning_effort,
        )
        new_job = generation.GenerationJob(
            requirement if resume_run is None else resume_run.requirement,
            ui_variant,
            pipeline_mode="layered",
            script_length=script_length,
            use_retrieval=not no_retrieval,
            run_id=resume_run.run_id if resume_run is not None else None,
            reasoning_effort=reasoning_effort,
        )
        try:
            new_job.start()
        except generation.GenerationBusyError as exc:
            st.error(str(exc))
        else:
            st.session_state["gen_job"] = new_job
            st.session_state.pop("gen_last_result", None)
            st.session_state.pop("gen_last_error", None)
            st.session_state.pop("gen_cancelled_result", None)
            st.rerun()

    if "gen_cancelled_result" in st.session_state:
        st.warning("已取消本次生成。")
        cancelled_result = st.session_state["gen_cancelled_result"]
        if cancelled_result is not None and cancelled_result.row:
            cancelled_run = RunRecord.from_row(
                cancelled_result.row, source_log=generation.UI_RUN_LOG.name
            )
            _render_run_meta(cancelled_run)
        if st.button("清除本次結果", key="clear_cancelled"):
            del st.session_state["gen_cancelled_result"]
            st.rerun()

    if "gen_last_error" in st.session_state:
        st.error(st.session_state["gen_last_error"])
        failed_result = st.session_state.get("gen_last_result")
        if failed_result is not None and failed_result.row:
            failed_run = RunRecord.from_row(
                failed_result.row, source_log=generation.UI_RUN_LOG.name
            )
            _render_run_meta(failed_run)
        if st.button("清除本次結果"):
            del st.session_state["gen_last_error"]
            st.session_state.pop("gen_last_result", None)
            st.rerun()

    if "gen_last_result" in st.session_state and "gen_last_error" not in st.session_state:
        result: generation.GenerationResult = st.session_state["gen_last_result"]
        rec = _record_for_result(result)
        _render_script(_load(rec), rec)
        if st.button("清除本次結果"):
            del st.session_state["gen_last_result"]
            st.rerun()

elif mode == "總覽表":
    st.title("總覽表")
    st.dataframe(_overview(include_checkpoints), width="stretch")

elif mode == "單篇閱讀":
    st.title("單篇閱讀")
    req_key = st.sidebar.selectbox(
        "劇情需求", requirement_keys, format_func=lambda k: _requirement_label(k, groups[k])
    )
    group = groups[req_key]
    variants = sorted({r.variant for r in group})
    variant = st.sidebar.selectbox("變體", variants)
    reps = sorted({r.rep for r in group if r.variant == variant})
    rep = st.sidebar.selectbox("Rep", reps) if len(reps) > 1 else reps[0]

    matches = [r for r in group if r.variant == variant and r.rep == rep]
    if len(matches) > 1:
        # Same (requirement, variant, rep) can collide across sources -- see
        # _record_label()'s docstring note. Let the user pick which one.
        rec = st.sidebar.selectbox(
            "紀錄", matches, format_func=lambda r: _record_label(r, disambiguate=True)
        )
    else:
        rec = matches[0] if matches else None
    if rec is None:
        st.info("找不到此組合的劇本。")
    elif rec.path is None:
        st.error("此次執行沒有產生劇本檔案（生成失敗）。")
        _render_run_meta(rec.run)
    else:
        script = _load(rec)
        if script is None:
            st.error(f"無法讀取此劇本檔案：`{rec.path}`（格式不符或已損壞）。")
            _render_run_meta(rec.run)
            _render_delete_button(rec)
        else:
            _render_script(script, rec)
            _render_delete_button(rec)

else:  # 並排比較
    st.title("並排比較")
    req_key = st.sidebar.selectbox(
        "劇情需求", requirement_keys, format_func=lambda k: _requirement_label(k, groups[k])
    )
    group = groups[req_key]
    all_variants = variant_names(group)
    selected = st.sidebar.multiselect("變體", all_variants, default=all_variants[:2])
    reps = sorted({r.rep for r in group})
    rep = st.sidebar.selectbox("Rep", reps) if len(reps) > 1 else (reps[0] if reps else 0)

    if not selected:
        st.info("請至少選擇一個變體。")
        st.stop()

    selected_records = []
    for variant in selected:
        rec = next((r for r in group if r.variant == variant and r.rep == rep), None)
        selected_records.append(rec)

    present = [r for r in selected_records if r is not None]
    if present:
        st.dataframe(overview_rows(present), width="stretch")

    show_all = st.checkbox("顯示全部事件（否則用序號滑桿逐一比對）", value=False)
    loaded = {r.key: _load(r) for r in present if r.path}
    max_events = max((len(s.events) for s in loaded.values() if s is not None), default=0)
    event_idx = None
    if not show_all and max_events > 0:
        event_idx = st.slider("事件序號", 1, max_events, 1) - 1

    cols = st.columns(len(selected))
    for col, variant, rec in zip(cols, selected, selected_records):
        with col:
            st.markdown(f"### {variant}")
            if rec is None:
                st.info("此變體無此需求的劇本")
                continue
            if rec.path is None:
                st.error("此次執行沒有產生劇本檔案（生成失敗）。")
                if rec.run is not None:
                    st.caption(rec.run.error)
                continue

            script = loaded.get(rec.key)
            if script is None:
                st.error(f"無法讀取此劇本檔案：`{rec.path}`（格式不符或已損壞）。")
                continue
            names = npc_names(script)
            titles = event_titles(script)
            chapters = chapter_names(script)
            clues = clue_names(script)
            st.caption(script.meta.title)
            problems = validate_references(script)
            st.caption("✅ 交叉參照無誤" if not problems else f"⚠️ {len(problems)} 個交叉參照問題")

            if show_all or event_idx is None:
                events_to_show = script.events
            elif event_idx < len(script.events):
                events_to_show = script.events[event_idx : event_idx + 1]
            else:
                events_to_show = []
            container = st.container(height=600) if show_all else st.container()
            with container:
                if not events_to_show:
                    st.caption("（此變體沒有這一個序號的事件）")
                for event in events_to_show:
                    st.markdown(f"**{event.title}**")
                    _render_event(event, names, titles, chapters, clues)
                    st.divider()
